async function bot(){const mine=++token;busy=true;const wait=()=>new Promise(r=>setTimeout(r,550));while(mine===token&&g.players[g.turn].bot&&g.winner===null){let steps=0;while(g.phase!=='done'&&g.winner===null&&mine===token&&steps++<70){const action=chooseBotAction(g,g.turn,g.phase==='door'?'prepare':g.phase);const ok=await executeBotAction(action);if(!ok){if(g.phase==='combat')await requestResolution('run');else if(g.phase==='loot'){busy=false;act('loot');busy=true}else{busy=false;act('door');busy=true}}render();await wait()}if(mine!==token)return;if(g.winner!==null)break;await wait();if(mine!==token)return;const actor=g.players[g.turn];actor.hand.sort((a,b)=>cardKeepValue(actor,b)-cardKeepValue(actor,a));endTurn(g);render()}busy=false}
function newGame(){modal('<h2>Начать новую историю?</h2><p>Текущая партия будет заменена после старта новой.</p><button class="primary" id="confirm-new">К выбору игроков</button><button class="text-btn" id="keep">Остаться за столом</button>');$('#confirm-new').onclick=()=>{close();lobby()};$('#keep').onclick=close}
function celebrate(){for(let i=0;i<40;i++){const e=document.createElement('i');e.className='confetti';e.style.cssText=`left:${Math.random()*100}%;background:${colors[i%5]};animation-delay:${Math.random()}s;transform:rotate(${Math.random()*360}deg)`;document.body.append(e);setTimeout(()=>e.remove(),4500)}}
function openGallery(){let visible=40;modal(`<div class="eyebrow">БЕСТИАРИЙ И БАРАХОЛКА</div><h2>Альбом карт</h2><p>✓ — проверенные правила, ◐ — часть эффектов или параметры подборки. Непроверенные особенности отложены. У каждой карты — подобранная иллюстрация. Один и тот же рисунок сохраняется в руке, бою и снаряжении.</p><div class="gallery-controls"><input id="gallery-search" placeholder="Монстр, предмет, класс…" aria-label="Поиск карт"><select id="gallery-set" aria-label="Набор карт"><option value="all">Все ${SETS.length} набора</option>${SETS.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="gallery-grid" id="gallery-grid"></div><p id="gallery-count" class="gallery-caption"></p><button class="outline" id="gallery-more">Показать ещё</button><p class="gallery-credits">Иллюстрации: <a href="https://game-icons.net" target="_blank" rel="noreferrer">Game-icons.net</a> · <a href="assets/cards/ATTRIBUTION.md" target="_blank">авторы</a> · CC BY 3.0. <a href="data/card-art.json" target="_blank">Источники по картам</a>.</p><button class="text-btn" id="close-gallery">Закрыть альбом</button>`);$('.modal').classList.add('card-gallery');function update(){const q=$('#gallery-search').value.trim().toLowerCase(),set=$('#gallery-set').value,cards=CARDS.filter(c=>(set==='all'||c.set===set)&&`${c.name} ${c.en}`.toLowerCase().includes(q));$('#gallery-grid').innerHTML=cards.slice(0,visible).map(c=>card(c)).join('');$('#gallery-count').textContent=`Показано ${Math.min(visible,cards.length)} из ${cards.length}`;$('#gallery-more').hidden=visible>=cards.length}$('#gallery-search').oninput=()=>{visible=40;update()};$('#gallery-set').onchange=()=>{visible=40;update()};$('#gallery-more').onclick=()=>{visible+=40;update()};$('#close-gallery').onclick=close;update()}
$('#gallery').onclick=openGallery;
$('#rules').onclick=()=>{modal(`<div class="eyebrow">ПАМЯТКА ПО ПРАВИЛАМ</div><h2>Две колоды. Восемь карт. Ни совести.</h2><ol class="rules-list"><li><b>Подготовка.</b> Двери и сокровища перемешиваются отдельно. Каждый получает 4 двери и 4 сокровища, начинает человеком 1 уровня без класса. Только карты на столе дают способности.</li><li><b>Дверь.</b> Открой верхнюю дверь: монстр начинает бой, проклятие срабатывает сразу, остальное берётся в руку. Если монстра нет, либо сыграй своего, либо возьми ещё одну закрытую дверь.</li><li><b>Бой.</b> Сила — уровень, шмотки, способности и разовые бонусы. Нужен перевес; воин на любой стороне искателей разрешает ничью. Один помощник рискует вместе с тобой. Соперники перед исходом получают окно подставы: Бродячая тварь + монстр, нежить к нежити, усилители, зелья и подрезки.</li><li><b>Способности.</b> Под рукой показаны постоянные эффекты и кнопки активных действий. Стоимость списывается только после выбора нужных карт. Мультиклассы и мультирасы объединяют эффекты разных активных карт. Условия и лимиты указаны в блоке персонажа.</li><li><b>Смывка.</b> От каждого монстра отдельный кубик: нужно 5 с учётом расовых бонусов. Волшебник и хафлинг могут использовать способности после неудачного броска. Смерть сохраняет классы, расы и уровень; новые 4+4 выдаются в начале собственного следующего хода.</li><li><b>Конец хода.</b> Лимит руки 5, у дварфа 6. Излишки поровну идут игрокам с самым низким уровнем. Если ты тоже самый низкий, они сбрасываются. У дверей и сокровищ отдельные сбросы; исчерпанная колода перемешивает только свой сброс.</li><li><b>Победа.</b> Достигни 10 уровня убийством монстра. Эльф получает по уровню за каждого монстра, убитого с его помощью, и так тоже может выиграть. Зачарование и приручение уровней не дают.</li></ol><p class="muted">Это адаптация подборок карт. Возврат снаряжения в руку, накопление золотых при продаже и часть редких эффектов упрощены. У проверенных предметов учтены цена, размер и ограничения; у исходных монстров — индивидуальные непотребства и условия боя. Не реализованы все дополнительные способности каждой печатной карты; блок персонажа перечисляет работающие.</p><p><a href="https://munchkin.game/site-munchkin/assets/files/1138/munchkin_rules-1.pdf" target="_blank" rel="noreferrer">Правила издателя</a> · <a href="https://munchkin.game/gameplay/faq/" target="_blank" rel="noreferrer">Официальные разъяснения</a></p><button class="primary" id="close-rules">Я всё понял. Наверное.</button>`);$('#close-rules').onclick=close};
$('#about').onclick=()=>{modal(`<h2>Фанатская подземка</h2><p>Манчкин принадлежит Steve Jackson Games. Это неофициальная локальная игра, не официальный Munchkin Digital.</p><p>В подборке ${CARDS.length} названий карт из ${SETS.length} наборов классического фэнтезийного Манчкина. Исходные три набора включены по умолчанию. Новые наборы содержат адаптированные подборки, а не полные колоды. Подземелья разыгрываются как события дверей, задания дают дополнительное сокровище, усилители меняют силу монстра. Это не полные колоды. Русские названия — описательные переводы, иллюстрации подобраны из Game-icons; авторы и лицензия указаны ниже. Эффекты и баланс адаптированы, оригинальные тексты и сканы не используются.</p><p>Иллюстрации: <a href="https://game-icons.net" target="_blank" rel="noreferrer">Game-icons.net</a> · <a href="assets/cards/ATTRIBUTION.md" target="_blank">авторы</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noreferrer">CC BY 3.0</a>. SVG-файлы не изменены, цвет и оформление добавлены через CSS. <a href="data/card-art.json" target="_blank">Источник каждой иллюстрации</a>.</p><p>Официальные списки названий сохранены в <a href="data/publisher-catalog.json" target="_blank">каталоге источников</a>. Источники: <a href="https://munchkin.game/" target="_blank" rel="noreferrer">Манчкин</a>, <a href="https://munchkin.game/products/games/munchkin/munchkin-2-unnatural-axe/" target="_blank" rel="noreferrer">Unnatural Axe</a>, <a href="https://munchkin.game/products/games/munchkin/munchkin-3-clerical-errors/" target="_blank" rel="noreferrer">Clerical Errors</a>, <a href="https://munchkin.game/gameplay/rules/" target="_blank" rel="noreferrer">правила издателя</a>.</p><button class="primary" id="close-about">Обратно в таверну</button>`);$('#close-about').onclick=close};$('#sound').onclick=()=>{sound=!sound;$('#sound').classList.toggle('enabled',sound);$('#sound').setAttribute('aria-label',sound?'Выключить звук':'Включить звук');beep();toast(sound?'Звуки таверны включены':'Таверна притихла')};$('#home').onclick=e=>{e.preventDefault();g?newGame():lobby()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#ready')&&!$('#reaction-ready')&&!$('#accept-bad')&&!$('#accept-bot-help')&&!$('#confirm-bad-stuff')&&!$('#die-pass'))close()});lobby();
